const toggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('nav');
toggle.addEventListener('click',()=>{const opened=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!opened));nav.classList.toggle('is-open',!opened)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('is-open');toggle.setAttribute('aria-expanded','false')}));
const services={
'real-estate':{title:'Real estate',intro:'Buying, selling, or making changes to a property can bring important legal questions. Discuss your plans and timelines with the firm.',topics:['What legal work is needed for my purchase or sale?','Which agreements and property documents should I bring?','What deadlines, costs, or financing details should we discuss?']},
wills:{title:'Wills & estates',intro:'Planning ahead starts with understanding your wishes and the people who matter to you. Ask about the documents and arrangements relevant to your circumstances.',topics:['What should I consider when preparing or updating a will?','How can I plan for decisions about my property and personal care?','What information should I gather about assets and beneficiaries?']},
family:{title:'Family law',intro:'Changes in family circumstances often come with difficult decisions. A discussion of your circumstances can help identify the questions that need attention.',topics:['What options should I discuss when considering a separation?','Which family agreements or financial documents may be relevant?','What questions should I ask about parenting, support, or property?']},
business:{title:'Business law',intro:'A business decision often has legal implications. Explore the questions connected with starting, operating, or making changes to your business.',topics:['What legal structure and documents should I consider?','Which contracts or ownership arrangements need review?','What should I prepare before buying, selling, or changing a business?']}
};
const dialog=document.querySelector('dialog');
const guideContent={
property:{title:'Before you pick up the keys',intro:'Prepare for a focused conversation about your purchase, sale, or refinancing. This checklist is a starting point, not legal advice.',topics:['Gather your signed agreement and any amendments, if you have them.','Note the important dates, including conditions, financing, and closing.','Collect any lender instructions and condominium documents that apply.','Ask which identification, fees, and additional documents the office requires.']},
planning:{title:'A thoughtful plan starts here',intro:'Organising your information can make a discussion about wills and powers of attorney more useful. Your lawyer can explain what is appropriate for your circumstances.',topics:['Make an overview of your assets, liabilities, and existing planning documents.','Think about the people or organisations you wish to provide for.','Consider whom you would want to discuss as an executor or attorney.','Write down questions about changes in your family, property, or wishes.']},
contracts:{title:'Before you sign the next agreement',intro:'Give your contract discussion a clear starting point. Ask about timing before committing to a signing deadline.',topics:['Bring the complete agreement, schedules, and relevant correspondence.','Explain the commercial goal and the obligations that matter most to you.','Identify deadlines and terms you would like clarified.','Ask about scope, review costs, and any further information needed.']}
};
document.querySelectorAll('[data-guide]').forEach(button=>button.addEventListener('click',()=>{const g=guideContent[button.dataset.guide];document.querySelector('#dialog-title').textContent=g.title;document.querySelector('#dialog-intro').textContent=g.intro;dialog.querySelector('h3').textContent='Your preparation checklist';dialog.querySelector('.dialog-note').textContent='General preparation information only. Discuss your individual circumstances with the firm.';document.querySelector('#dialog-topics').replaceChildren(...g.topics.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));dialog.showModal()}));
document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{dialog.querySelector('h3').textContent='Questions to bring to your discussion';dialog.querySelector('.dialog-note').textContent='Illustrative service descriptions for review. The firm will confirm whether it can assist with your particular matter.'}));
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{const s=services[button.dataset.service];document.querySelector('#dialog-title').textContent=s.title;document.querySelector('#dialog-intro').textContent=s.intro;const list=document.querySelector('#dialog-topics');list.replaceChildren(...s.topics.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));dialog.showModal()}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
document.querySelector('#dialog-contact').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});

